  const nodes=[...groups.values()].sort((a,b)=>a.id.localeCompare(b.id));for(const neighbor of neighborRepos){const counts=repoSummary(ctx,neighbor,graph);nodes.push({...counts,id:`neighbor:${neighbor}`,label:`${shortName(neighbor)}\n${counts.services}s · ${counts.routes}r · ${counts.infra}i`,kind:'neighbor_aggregate',repo:neighbor,repos:[neighbor],aggregate:true,counts});}
  const shown=nodes.slice(0,limits.maxNodes),ids=new Set(shown.map(node=>node.id)),memberToGroup=new Map();for(const group of shown)for(const id of group.memberIds||[])memberToGroup.set(id,group.id);const neighborIds=new Map(neighborRepos.map(value=>[value,`neighbor:${value}`]));
  const records=[];for(const edge of ctx.edges){if(!modeAllows(mode,{edge}))continue;const from=ctx.byId.get(edge.from);if(!from)continue;for(const targetId of endpointTargets(edge)){const target=ctx.byId.get(targetId);if(!target||(from.repo!==repo&&target.repo!==repo))continue;records.push({edge,target:targetId,fromRepo:from.id,toRepo:target.id});}}
  const endpointGroup=id=>memberToGroup.get(id)||neighborIds.get(ctx.byId.get(id)?.repo),aggregated=aggregateEdges(records,value=>endpointGroup(value),limits),edges=aggregated.edges.filter(edge=>ids.has(edge.source)&&ids.has(edge.target));
  return{mode,level:1,title:repo,scope:{repo},nodes:shown,edges,totalNodes:nodes.length,totalEdges:aggregated.total,reason:'canonical relationships aggregated between semantic groups',guidance:edges.length?null:{kind:'empty-mode',message:`No ${modeName(mode)} relationships connect the available groups. Try another data-bearing mode or repository.`}};
