    for(const node of needed)addNode(node);
    rawEdges.push({...edge,id:index?`${edge.id}:candidate:${index}`:edge.id,canonicalId:edge.id,source:from.id,target:target.id,family:edgeFamily(edge.kind),count:edge.parallel_count||1,statuses:{[edge.status||'resolved']:1},rawIds:[edge.id],raw:true});
